import { Component, OnInit } from '@angular/core';

@Component({
  selector: 'lib-password-validation',
  template: `
  <p>passowrd-validator works!</p>
  <table>
      <tr>
          <td>Username: </td>
          <td><input type="text" placeholder="Enter username" [(ngModel)]="username"></td>
      </tr>
      <tr>
          <td>Password: </td>
          <td><input type="text" placeholder="Enter password" [(ngModel)]="password"></td>
      </tr>
      <tr>
          <td><button (click)="passwordValidate()">Submit</button></td>
      </tr>
      <tr>
          <td colspan="2">{{message}}</td>
      </tr>
  </table>
  `,
  styles: [
  ]
})
export class PasswordValidationComponent implements OnInit {
  message:string="";
  password:string="";
  username:string="";
  passwordValidate()
  {
    if(this.password.length==0)
    {
      this.message="Password should not be left empty";
    }
    else if(this.password.length<8)
    {
       this.message="Password is less than the specified minimum length";
    }
    else if(this.password.length>20)
    {
      this.message="Password length is greater than the specified length";
    }
    else
    {
      this.message="Your password is valid";
    }
    
  }
  constructor() { }

  ngOnInit(): void {
  }

}
